__NUXT_JSONP__("/mougins", (function(a,b,c,d,e,f,g,h,i){return {data:[{dataLoaded:true,metas:{title:"Dinner in the sky - France",description:"Du 13 au 22 septembre, en France",image:"https:\u002F\u002Fdinnerinthesky.be\u002Fimg\u002Fbackground\u002FDITS-2024-Neutral.png"},blocks:[{type:"hero_home",content:{id:"home",tagline:a,title:"$dates_long",subtitle:"POUR LA TOUTE PREMIERE FOIS\u003Cbr\u002F\u003EDANS LE CIEL DE \u003Cstrong\u003EMOUGINS\u003C\u002Fstrong\u003E",place:a,image:{desktop:"\u002Fimg\u002Fbackground\u002FDITS-2024-Neutral.png",mobile:"\u002Fimg\u002Fbackground\u002FDITS-2024-Neutral_Mobile.png"},text:a}},{type:d,content:{id:d,tagline:"DITS",title:"Une expérience gastronomique unique, la tête dans les étoiles",text:"\u003Cp\u003EAprès Monaco, Rome, Beyrouth, Tokyo, Dubaï ou encore Las Vegas, Dinner in the Sky\u003Csup\u003E®\u003C\u002Fsup\u003E s’installe pour la première fois, au cœur de Mougins, berceau du Festival des Etoiles.\u003C\u002Fp\u003E\u003Cp\u003ELe temps d’un déjeuner, d’un dîner, d’une pause gourmande ou un brunch, prenez de la hauteur pour vivre une expérience gustative extra-ordinaire et profiter d’une vue imprenable sur la méditerranée et l’arrière-pays cannois.\u003C\u002Fp\u003E",images1:[],images2:[]}},{type:"image_text_cta",content:{id:b,tagline:b,title:"Le Concept",text:"\u003Cp\u003EDinner in the Sky\u003Csup\u003E®\u003C\u002Fsup\u003E est une expérience gastronomique extraordinaire qui repose sur les notions de surprise et de découverte tant dans le menu que dans la rencontre et l’échange avec le Chef ou le Chocolatier\u002FPâtissier avec qui vous embarquez.\u003C\u002Fp\u003E\u003Cp\u003EEn plein ciel de Mougins, une table de \u003Cstrong\u003E22 personnes\u003C\u002Fstrong\u003E est suspendue dans les airs. Au centre de la table se trouve un espace cuisine permettant aux Chefs de préparer et de servir, face à vous, un repas d’exception.\u003C\u002Fp\u003E\u003Cp\u003ECet incroyable concept débarquera pour la \u003Cstrong\u003E1\u003Csup\u003Eère\u003C\u002Fsup\u003E fois à Mougins\u003C\u002Fstrong\u003E, \u003Cstrong\u003E$dates\u003C\u002Fstrong\u003E, pour :\u003C\u002Fp\u003E\u003Cul\u003E\u003Cli\u003E\u003Cstrong\u003E2 déjeuners par jour\u003C\u002Fstrong\u003E,\u003C\u002Fli\u003E\u003Cli\u003E\u003Cstrong\u003E1 goûters par jour\u003C\u002Fstrong\u003E\u003C\u002Fli\u003E\u003Cli\u003E\u003Cstrong\u003E2 dîners par jour\u003C\u002Fstrong\u003E\u003C\u002Fli\u003E\u003C\u002Ful\u003E\u003Cp\u003EAu total \u003Cstrong\u003E770 personnes\u003C\u002Fstrong\u003E pourront déguster des mets raffinés la tête dans les étoiles…\u003C\u002Fp\u003E",image:"\u002Fimg\u002Fgallery\u002FMougins.jpg",cta:{text:"Réservez maintenant",route:"#booking",gtm:{action:b,position:b}}}},{type:e,content:{id:e,tagline:"L'experience",title:"Choisissez l'expérience que vous souhaitez",text:"\u003Cp\u003EDinner in the sky propose différentes formules pour répondre à toutes les envies.\u003C\u002Fp\u003E\u003Cp\u003EDu 13 au 22 septembre, Avenue du Moulin de la Croix 89 (Parking)\u003C\u002Fp\u003E",formulas:[{title:"Lunch 1 & 2 - 295€",text:"\u003Cp\u003EVivez une expérience Lunch in the Sky avec le chef de votre choix ! Du Lundi au Dimanche, Dinner in the Sky vous accueille pour une coupe de Champagne dans notre VIP Lounge. Ensuite, décollage prévu en douceur avec vos invités ; famille, amis, collègues ou clients vivront un moment inoubliable… \u003C\u002Fp\u003E",text2:"\u003Ch4\u003ELa formule comprend :\u003C\u002Fh4\u003E\u003Cul\u003E\u003Cli\u003EL’accueil Champagne dans notre VIP Lounge,\u003C\u002Fli\u003E\u003Cli\u003ELe menu 3 services préparé par le Chef du jour,\u003C\u002Fli\u003E\u003Cli\u003EL’accord mets & vins,\u003C\u002Fli\u003E\u003Cli\u003EL’eau et les softs à table,\u003C\u002Fli\u003E\u003Cli\u003ELe café dans notre VIP Lounge,\u003C\u002Fli\u003E\u003C\u002Ful\u003E",text3:"\u003Ch4\u003ETiming du Lunch 1 :\u003C\u002Fh4\u003E\u003Cul\u003E\u003Cli\u003E11h00 : Accueil Champagne au sein du VIP Lounge\u003C\u002Fli\u003E\u003Cli\u003E12h00 : Décollage\u003C\u002Fli\u003E\u003Cli\u003E13h15 : Atterrissage\u003C\u002Fli\u003E\u003Cli\u003E14h00 : Café dans le VIP Lounge\u003C\u002Fli\u003E\u003C\u002Ful\u003E\u003Ch4\u003ETiming du Lunch 2 :\u003C\u002Fh4\u003E\u003Cul\u003E\u003Cli\u003E13h00 : Accueil Champagne au sein du VIP Lounge\u003C\u002Fli\u003E\u003Cli\u003E14h00 : Décollage\u003C\u002Fli\u003E\u003Cli\u003E15h15 : Atterrissage\u003C\u002Fli\u003E\u003Cli\u003E16h00 : Café dans le VIP Lounge\u003C\u002Fli\u003E\u003C\u002Ful\u003E",image:"\u002Fimg\u002Fgallery\u002F11209472_1574094252811244_8917164324048276224_n.jpg",cta:{text:"Réservez votre Lunch",link:c}},{title:"Goûter in the Sky - 150€",text:"\u003Cp\u003EDinner in the Sky c’est un moment hors du temps, une pause gourmande en toute intimité au plus proche du Chef de votre choix. La cuisine ouverte à 360° permet à vos invités d’être en contact constant avec le Chef du jour et de découvrir ses secrets de cuisine…\u003C\u002Fp\u003E",text2:"\u003Ch4\u003ELa formule comprend :\u003C\u002Fh4\u003E\u003Cul\u003E\u003Cli\u003EL’accueil Champagne dans notre VIP Lounge,\u003C\u002Fli\u003E\u003Cli\u003EUne dégustation de pâtisseries et\u002Fou chocolats\u003C\u002Fli\u003E\u003Cli\u003EL’accord mets & vins,\u003C\u002Fli\u003E\u003Cli\u003EL’eau et les softs à table,\u003C\u002Fli\u003E\u003Cli\u003ELe café dans notre VIP Lounge,\u003C\u002Fli\u003E\u003C\u002Ful\u003E",text3:"\u003Ch4\u003ETiming du Goûter in the Sky :\u003C\u002Fh4\u003E\u003Cul\u003E\u003Cli\u003E15h45 : Accueil au sein du VIP Lounge\u003C\u002Fli\u003E\u003Cli\u003E16h15 : Décollage\u003C\u002Fli\u003E\u003Cli\u003E17h00 : Atterrissage & Fin\u003C\u002Fli\u003E\u003C\u002Ful\u003E",image:"\u002Fimg\u002Fexperience\u002FCocktail.jpg",cta:{text:"Réservez votre Goûter",link:c}},{title:"Dîner 1 & 2 - 295€",text:"\u003Cp\u003EDinner in the Sky c’est un moment hors du temps, un dîner en toute intimité au plus proche du Chef de votre choix. La cuisine ouverte à 360° permet à vos invités d’être en contact constant avec le Chef du jour et de découvrir ses secrets de cuisine… Deux repas sont organisés le soir, de quoi satisfaire tout le monde !\u003C\u002Fp\u003E",text2:"\u003Ch4\u003ELa formule comprend :\u003C\u002Fh4\u003E\u003Cul\u003E\u003Cli\u003EL’accueil Champagne dans notre VIP Lounge,\u003C\u002Fli\u003E\u003Cli\u003ELe menu 4 services préparé par le Chef du jour,\u003C\u002Fli\u003E\u003Cli\u003EL’accord mets & vins,\u003C\u002Fli\u003E\u003Cli\u003EL’eau et les softs à table,\u003C\u002Fli\u003E\u003Cli\u003ELe café dans notre VIP Lounge,\u003C\u002Fli\u003E\u003C\u002Ful\u003E",text3:"\u003Ch4\u003ETiming du Dinner 1 :\u003C\u002Fh4\u003E\u003Cul\u003E\u003Cli\u003E18h00 : Accueil Champagne au sein du VIP Lounge\u003C\u002Fli\u003E\u003Cli\u003E19h00 : Décollage\u003C\u002Fli\u003E\u003Cli\u003E20h15 : Atterrissage\u003C\u002Fli\u003E\u003Cli\u003E21h00 : Café dans le VIP Lounge\u003C\u002Fli\u003E\u003C\u002Ful\u003E\u003Ch4\u003ETiming du Dinner 2 :\u003C\u002Fh4\u003E\u003Cul\u003E\u003Cli\u003E20h00 : Accueil Champagne au sein du VIP Lounge\u003C\u002Fli\u003E\u003Cli\u003E21h00 : Décollage\u003C\u002Fli\u003E\u003Cli\u003E22h15 : Atterrissage\u003C\u002Fli\u003E\u003Cli\u003E23h00 : Café dans le VIP Lounge\u003C\u002Fli\u003E\u003C\u002Ful\u003E",image:"\u002Fimg\u002Fgallery\u002FJJ5_7049.jpg",cta:{text:"Réservez votre Dîner",link:c}}]}},{type:f,content:{id:f,tagline:"Nos chefs",title:"Chefs Dream Team 2024",text:"\u003Cp\u003EUne vingtaine de talents gastronomiques dont de nombreux Chefs MOF étoilés participeront à cet événement culinaire hors norme.\u003C\u002Fp\u003E"}},{type:g,content:{id:g,tagline:"Inscrivez-vous",title:"Liste d’attente",text:"\u003Cp\u003EInscrivez-vous sur notre liste d’attente pour recevoir un e-mail si des places se libèrent.\u003C\u002Fp\u003E",image:"\u002Fimg\u002Fgallery\u002FKOVA8323.jpg"}},{type:"gallery",content:{id:"medias",tagline:"Photos & Vidéos",title:"Media Gallery",text:a}},{type:h,content:{id:h,tagline:"partenaires",title:"Nos partenaires",text:a}},{type:i,content:{id:i,tagline:"En savoir plus\u003Cbr\u002F\u003E\u003Cstrong\u003Esur notre histoire\u003C\u002Fstrong\u003E",title:"C'est une histoire surréaliste comme la Belgique les aime tant",text1:"\u003Cp\u003EC'est une histoire surréaliste comme la Belgique les aime tant: il y a 18 ans, The Fungroup, société spécialisée dans les attractions liées aux grues et Hakuna Matata, agence de communication spécialisée en gastronomie, s'associent et réalisent un rêve d’enfant: une table volante baptisée Dinner in the Sky (\u003Ca href=\"http:\u002F\u002Fwww.dinnerinthesky.com\" target=\"_blank\"\u003Ewww.dinnerinthesky.com\u003C\u002Fa\u003E) autour de laquelle ont pris place pour l’occasion 22 Jeunes Restaurateurs d’Europe coiffés de leur toque blanche.\u003C\u002Fp\u003E\u003Cp\u003E15 ans plus tard Dinner in the Sky sillonne les cieux de plus de 60 pays… L’Europe bien sûr mais aussi l’Australie, l’Inde, Dubaï, l’Afrique du Sud, le Brésil, les Etats-Unis, le Canada, le Japon, la Colombie, le Mexique.\u003C\u002Fp\u003E\u003Cp\u003EAu cours de ces cinq années, des dîners incroyables ont été réalisés - par exemple celui organisé dans le ciel de Monaco pour le Prince Albert avec Joël Robuchon aux commandes, le chef le plus étoilé de France - mais aussi plus de 1.000 événements, chacun unique en leur genre, de Paris à Las Vegas en passant par Sydney, Le Cap, Londres ou encore Sao Paulo. \u003C\u002Fp\u003E",text2:"\u003Cp\u003ELes plus belles étoiles de la gastronomie ont pris place derrière les fourneaux: de Pierre Gagnaire à Marc Veyrat, d’Yves Mattagne à Sergio Herman, de Dani Garcia à Paco Roncero, d’Alain Passard à Yannick Alleno,… \u003C\u002Fp\u003E\u003Cp\u003ELes lieux les plus magiques ont été survolés : le Strip de Vegas, les jardins de l’Hôtel King David, la Marina de Dubaï, les collines de la Villa Borghese, le circuit de Spa Francorchamps, les Rives du Saint-Laurent, la plage de Copacabana, la baie de Cape Town… \u003C\u002Fp\u003E\u003Cp\u003ELes plus grands media se sont intéressés au concept : ABC, NBC, TF1… le Herald Tribune, le Monde, le Frankfurter Algemein… People Magazine, Elle, Forbes… aux travers des célèbres personnalités qui s’y sont attablées : le Prince de Suède, la présentatrice Japonaise Hiromi Iwasaki, le maire de Las Vegas Oscar B. Goodman…\u003C\u002Fp\u003E",bg:{pretitle:"Depuis",title:"2006",img:"\u002Fimg\u002FDITS-logo-cloud.png"}}}]}],fetch:{},mutations:[]}}("","concept","https:\u002F\u002Fdinner-in-the-sky-mougins.eventsquare.store\u002Ffr","dits","experience","chefs","booking","partners","knowmore")));